const root = globalThis;
const players = runtimeScene.getObjects("Player");
const coins = runtimeScene.getObjects("Coin");
const statuses = runtimeScene.getObjects("Status");

const player = players[0];
const coin = coins[0];
const status = statuses[0];
const scoreVar = runtimeScene.getVariables().get("score");

if (!root.__JM_GDEVELOP_RECEIPT__) {
  root.__JM_GDEVELOP_RECEIPT__ = {
    schema: "JM.TargetBridge.GDevelopReceipt/0.2",
    source_authority: "JM",
    host: "GDevelop",
    real_host: true,
    body_id: "jm.target-bridge.mini-collect-contact/v0.8",
    observations: {
      movement: "WAIT",
      contact: "WAIT",
      score_delta: "WAIT",
      coin_consumption: "WAIT"
    },
    values: {
      score_before: scoreVar.getAsNumber(),
      score_after: scoreVar.getAsNumber()
    },
    unresolved_preserved: [
      "hazard.consequence",
      "goal.after_collecting",
      "starting_player_hp"
    ],
    trace: []
  };
}

const receipt = root.__JM_GDEVELOP_RECEIPT__;
const pushOnce = (type, detail) => {
  if (!receipt.trace.some(entry => entry.type === type)) {
    receipt.trace.push({
      seq: receipt.trace.length + 1,
      type,
      detail
    });
  }
};

if (player && gdjs.evtTools.input.isKeyPressed(runtimeScene, "Right")) {
  const beforeX = player.getX();
  const dt = gdjs.evtTools.runtimeScene.getElapsedTimeInSeconds(runtimeScene);
  player.setX(beforeX + 300 * dt);
  const afterX = player.getX();

  if (afterX > beforeX) {
    receipt.observations.movement = "PASS";
    pushOnce("movement", { before_x: beforeX, after_x: afterX, input: "Right" });
  }
}

if (player && coin && gdjs.RuntimeObject.collisionTest(player, coin, false)) {
  const scoreBefore = scoreVar.getAsNumber();
  receipt.observations.contact = "PASS";
  pushOnce("contact", { left: "Player", right: "Coin", contact_true: true });

  scoreVar.setNumber(1);
  const scoreAfter = scoreVar.getAsNumber();
  receipt.values.score_before = scoreBefore;
  receipt.values.score_after = scoreAfter;

  if (scoreBefore === 0 && scoreAfter === 1) {
    receipt.observations.score_delta = "PASS";
    pushOnce("score_delta", { before: scoreBefore, after: scoreAfter });
  }

  coin.deleteFromScene();
  receipt.observations.coin_consumption = "PASS";
  pushOnce("coin_consumption", { before: true, after: false });
}

if (status) {
  const allPass =
    receipt.observations.movement === "PASS" &&
    receipt.observations.contact === "PASS" &&
    receipt.observations.score_delta === "PASS" &&
    receipt.observations.coin_consumption === "PASS";

  status.setText(
    "JM TARGET BRIDGE → GDEVELOP\n" +
    "movement: " + receipt.observations.movement +
    " | contact: " + receipt.observations.contact +
    " | score: " + scoreVar.getAsNumber() +
    " | coin consumed: " + receipt.observations.coin_consumption +
    (allPass ? "\nBOUNDED HOST CONTACT: PASS" : "")
  );

  if (allPass && !receipt.completed) {
    receipt.completed = true;
    receipt.completed_at_runtime_ms = runtimeScene.getTimeManager().getTimeFromStart();
    console.log("JM TARGET BRIDGE GDEVELOP CONTACT PASS", receipt);
  }
}
